<style>
body :is(a,button).swe-action-primary{background:var(--swe-palette-hex-641b2a,#641b2a);color:#fff;border-color:var(--swe-palette-hex-641b2a,#641b2a);transition:background-color .2s ease,color .2s ease}
body :is(a,button).swe-action-primary:hover{background:var(--swe-palette-hex-4d1421,#4d1421);border-color:var(--swe-palette-hex-4d1421,#4d1421);color:#fff}
body :is(a,button).swe-action-primary:active{background:var(--swe-palette-hex-3c101a,#3c101a)}
body :is(a,button).swe-action-danger{background:var(--swe-palette-hex-fff7f3,#fff7f3);border:1px solid var(--swe-palette-hex-9b4c49,#9b4c49);color:var(--swe-palette-hex-782d32,#782d32);transition:background-color .2s ease,color .2s ease}
body :is(a,button).swe-action-danger:hover{background:var(--swe-palette-hex-782d32,#782d32);border-color:var(--swe-palette-hex-782d32,#782d32);color:#fff}
body :is(a,button).swe-action-danger:active{background:var(--swe-palette-hex-641b2a,#641b2a);color:#fff}
body :is(.swe-action-primary,.swe-action-danger):focus-visible{outline:2px solid var(--swe-palette-hex-b78a54,#b78a54);outline-offset:3px}
body button:is(.swe-action-primary,.swe-action-danger):disabled{opacity:.55;cursor:not-allowed}
.swe-unified .swe-danger-zone{border-color:var(--swe-palette-hex-d9b6a8,#d9b6a8)}
.swe-unified .swe-danger-zone h2{color:var(--swe-palette-hex-782d32,#782d32)}
.swe-unified .swe-danger-panel{background:var(--swe-palette-hex-f5e9e0,#f5e9e0);border:1px solid var(--swe-palette-hex-e5cfc0,#e5cfc0)}
@media(prefers-reduced-motion:reduce){body :is(a,button).swe-action-primary,body :is(a,button).swe-action-danger{transition:none}}
.swe-unified .peer:checked ~ .swe-theme-switch{background:var(--swe-palette-hex-641b2a,#641b2a)}
